package com.shale.data.dao;
import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import org.junit.jupiter.api.Test;
class SessionSecurityAuditMigrationContractTest{
	@Test void migrationIsBoundedTenantProtectedAndAddsOnlyRequiredReason()throws Exception{String s=Files.readString(Path.of("../docs/sql/2026-09-29_session_security_audit_phase8a.sql"));for(String x:new String[]{"SessionSecurityAuditLog","USER_REVOKED","ADMIN_SESSION_LIST","ADMIN_REVOKE","sec.fn_FilterByTenant","AFTER INSERT","AFTER UPDATE"})assertTrue(s.contains(x),x);assertFalse(s.contains("Token"));assertFalse(s.contains("Jti"));}
	@Test void liveRlsVerifierImpersonatesNonDboAndExercisesAllFourEnforcementChecks()throws Exception{String s=Files.readString(Path.of("../docs/sql/verification/2026-09-29_session_security_audit_phase8a_rls.sql"));for(String x:new String[]{"CREATE USER [Phase8ARlsVerifier] WITHOUT LOGIN","EXECUTE AS USER = N'Phase8ARlsVerifier'","@value = 7","SameTenantInsertAndVisibility","CrossTenantVisibilityFiltered","CrossTenantInsertBlocked33504","CrossTenantUpdateBlocked33504","ERROR_NUMBER() = 33504","REVERT","DROP USER [Phase8ARlsVerifier]"})assertTrue(s.contains(x),x);assertFalse(s.contains("EXECUTE AS USER = N'dbo'"));}
	@Test void interruptedVerifierCleanupTargetsOnlyRecognizableFixturesAndPrincipal()throws Exception{String s=Files.readString(Path.of("../docs/sql/verification/2026-09-29_session_security_audit_phase8a_rls_cleanup.sql"));assertTrue(s.contains("@value = NULL"));assertTrue(s.contains("8A000000-0000-4000-8000-000000000007"));assertTrue(s.contains("8A000000-0000-4000-8000-000000000008"));assertTrue(s.contains("DROP USER [Phase8ARlsVerifier]"));assertFalse(s.contains("DELETE dbo.SessionSecurityAuditLog;"));}
}
